public async Task<IActionResult> EnableAuthenticator()
{
    var user = await _userManager.GetUserAsync(User);
    if (user == null) return NotFound();

    await _userManager.ResetAuthenticatorKeyAsync(user);

    var key = await _userManager.GetAuthenticatorKeyAsync(user);
    if (string.IsNullOrEmpty(key))
    {
        await _userManager.ResetAuthenticatorKeyAsync(user);
        key = await _userManager.GetAuthenticatorKeyAsync(user);
    }

    var model = new EnableAuthenticatorViewModel
    {
        SharedKey = FormatKey(key),
        QrCodeUrl = $"otpauth://totp/Quotient:{user.Email}?secret={key}&issuer=Quotient"
    };

    return View(model);
}

[HttpPost]
public async Task<IActionResult> EnableAuthenticator(EnableAuthenticatorViewModel model)
{
    var user = await _userManager.GetUserAsync(User);
    if (user == null) return NotFound();

    var isValid = await _userManager.VerifyTwoFactorTokenAsync(
        user, _userManager.Options.Tokens.AuthenticatorTokenProvider, model.Code);

    if (!isValid)
    {
        ModelState.AddModelError("Code", "Invalid authenticator code");
        return View(model);
    }

    await _userManager.SetTwoFactorEnabledAsync(user, true);
    TempData["StatusMessage"] = "Authenticator app enabled!";
    return RedirectToAction(nameof(ShowRecoveryCodes));
}

public async Task<IActionResult> GenerateRecoveryCodes(int numberOfCodes = 10)
{
    var user = await _userManager.GetUserAsync(User);
    if (user == null) return NotFound();

    var codes = await _userManager.GenerateNewTwoFactorRecoveryCodesAsync(user, numberOfCodes);

    var formattedCodes = codes.Select(code => code.Insert(4, "-")
        .Insert(9, "-"));

    ViewBag.RecoveryCodes = formattedCodes.ToArray();
    return View();
}

